import os,sys,re
roots=['/usr/share/doc','/usr/local/lib/python3.11/site-packages/sage']
pat=re.compile(rb'AW\*[- ]algebra|AW\^\*|monotone.complete.C\*|quasitrace',re.I)
hits=[];count=0
for root in roots:
 for base,dirs,files in os.walk(root):
  dirs[:]=[d for d in dirs if d not in ['__pycache__','.git','node_modules']]
  for f in files:
   if not f.endswith(('.py','.txt','.rst','.md','.html','.tex')):continue
   p=os.path.join(base,f)
   try:
    if os.path.getsize(p)>4000000:continue
    data=open(p,'rb').read();count+=1
    if pat.search(data):
     hits.append(p)
     for line in data.splitlines():
      if pat.search(line):print(p,line[:400].decode(errors='replace'))
   except OSError:pass
print('Searched',count,'local text files; matching files:',len(hits))

